Here is a production-grade, fully typed implementation followed by a usage example and architectural trade-off analysis.

```typescript
/**
 * ETL Job Queue - Rate-limited, concurrent, retry-aware async processor
 * Designed for overnight batch pipelines where failure isolation and 
 * predictable throughput are critical.
 */

export interface EtlQueueOptions {
  /** Maximum number of jobs running simultaneously */
  concurrency: number;
  /** Maximum requests per second across all workers */
  maxRPS: number;
  /** Base delay in ms before first retry */
  retryBaseDelayMs: number;
  /** Number of retry attempts after initial failure */
  maxRetries: number;
  /** Optional signal for graceful cancellation */
  signal?: AbortSignal;
}

export type EtlJob<T, R> = (item: T, signal: AbortSignal) => Promise<R>;

export interface EtlQueueResult<R> {
  successes: number;
  failures: number;
  errors: Array<{ item: unknown; error: unknown }>;
  /** Results are unordered due to concurrent execution */
  results: R[];
}

/**
 * Token Bucket Rate Limiter
 * Smoothly enforces maxRPS with sub-millisecond precision where possible.
 */
class TokenBucket {
  private tokens: number;
  private lastRefill: number;

  constructor(private readonly maxRPS: number) {
    this.tokens = maxRPS;
    this.lastRefill = Date.now();
  }

  private refill(): void {
    const now = Date.now();
    const elapsed = (now - this.lastRefill) / 1000;
    this.tokens = Math.min(this.maxRPS, this.tokens + elapsed * this.maxRPS);
    this.lastRefill = now;
  }

  async acquire(signal: AbortSignal): Promise<void> {
    while (true) {
      if (signal.aborted) throw new DOMException('Operation aborted', 'AbortError');
      this.refill();
      if (this.tokens >= 1) {
        this.tokens -= 1;
        return;
      }
      const waitMs = ((1 - this.tokens) / this.maxRPS) * 1000;
      await this.waitForAbortOrTimeout(waitMs, signal);
    }
  }

  private waitForAbortOrTimeout(ms: number, signal: AbortSignal): Promise<void> {
    return new Promise<void>((resolve, reject) => {
      const timer = setTimeout(resolve, ms);
      signal.addEventListener('abort', () => {
        clearTimeout(timer);
        reject(new DOMException('Operation aborted', 'AbortError'));
      }, { once: true });
    });
  }
}

export class EtlJobQueue<T, R> {
  constructor(private readonly options: EtlQueueOptions) {
    if (options.concurrency < 1) throw new RangeError('concurrency must be >= 1');
    if (options.maxRPS < 1) throw new RangeError('maxRPS must be >= 1');
    if (options.retryBaseDelayMs < 0) throw new RangeError('retryBaseDelayMs must be >= 0');
    if (options.maxRetries < 0) throw new RangeError('maxRetries must be >= 0');
  }

  async execute(items: T[], jobFn: EtlJob<T, R>): Promise<EtlQueueResult<R>> {
    const { concurrency, maxRPS, retryBaseDelayMs, maxRetries, signal } = this.options;
    const bucket = new TokenBucket(maxRPS);
    const safeSignal = signal ?? new AbortController().signal;

    // Fail fast if already aborted
    if (safeSignal.aborted) {
      return { successes: 0, failures: 0, errors: [], results: [] };
    }

    const result: EtlQueueResult<R> = { successes: 0, failures: 0, errors: [], results: [] };
    let currentIndex = 0;

    const worker = async (): Promise<void> => {
      while (currentIndex < items.length) {
        if (safeSignal.aborted) break;
        const itemIndex = currentIndex++;
        const item = items[itemIndex];

        let lastError: unknown;
        let attempt = 0;

        while (true) {
          if (safeSignal.aborted) throw new DOMException('Operation aborted', 'AbortError');

          try {
            // 1. Acquire rate limit token
            await bucket.acquire(safeSignal);
            // 2. Execute job
            const jobResult = await jobFn(item, safeSignal);
            result.results.push(jobResult);
            result.successes++;
            break; // Success, move to next item
          } catch (err) {
            lastError = err;
            if (safeSignal.aborted) throw err;
            if (err instanceof DOMException && err.name === 'AbortError') throw err;

            // 3. Retry logic
            if (attempt < maxRetries) {
              const delay = this.calculateDelay(attempt, retryBaseDelayMs);
              await this.waitForAbortOrTimeout(delay, safeSignal);
            } else {
              // Exhausted retries
              result.failures++;
              result.errors.push({ item, error: lastError });
              break;
            }
            attempt++;
          }
        }
      }
    };

    try {
      // Spawn fixed worker pool
      await Promise.all(Array.from({ length: concurrency }, () => worker()));
    } catch (err) {
      if (err instanceof DOMException && err.name === 'AbortError') {
        // Graceful cancellation: return partial results accumulated so far
      } else {
        throw err;
      }
    }

    return result;
  }

  /** Exponential backoff with full jitter: delay = base * 2^attempt + random(0, base) */
  private calculateDelay(attempt: number, baseDelay: number): number {
    const exponential = baseDelay * Math.pow(2, attempt);
    const jitter = Math.random() * baseDelay;
    return exponential + jitter;
  }

  private waitForAbortOrTimeout(ms: number, signal: AbortSignal): Promise<void> {
    return new Promise<void>((resolve, reject) => {
      const timer = setTimeout(resolve, ms);
      signal.addEventListener('abort', () => {
        clearTimeout(timer);
        reject(new DOMException('Operation aborted', 'AbortError'));
      }, { once: true });
    });
  }
}
```

### Usage Example

```typescript
import { EtlJobQueue, EtlQueueOptions, EtlJob } from './etl-queue';

async function runPipeline() {
  const controller = new AbortController();

  // Simulate upstream cancellation after 3 seconds
  setTimeout(() => controller.abort(), 3000);

  const options: EtlQueueOptions = {
    concurrency: 4,
    maxRPS: 10,
    retryBaseDelayMs: 200,
    maxRetries: 2,
    signal: controller.signal,
  };

  const queue = new EtlJobQueue<string, { id: string; status: string }>(options);

  const payload = Array.from({ length: 50 }, (_, i) => `record-${i}`);

  const jobFn: EtlJob<string, { id: string; status: string }> = async (id, signal) => {
    if (signal.aborted) throw new DOMException('Aborted', 'AbortError');

    // Simulate network/DB call
    await new Promise(resolve => setTimeout(resolve, 100 + Math.random() * 200));

    // Simulate 20% random failure rate
    if (Math.random() < 0.2) throw new Error(`Transient failure for ${id}`);

    return { id, status: 'processed' };
  };

  const result = await queue.execute(payload, jobFn);

  console.log(`Completed: ${result.successes} successes, ${result.failures} failures`);
  console.log(`Errors:`, result.errors);
}

runPipeline();
```

### Architectural Trade-offs & Design Notes

| Decision | Rationale | Trade-off |
|----------|-----------|-----------|
| **Fixed Worker Pool + Shared Index** | Avoids promise queue overhead and lock contention. `currentIndex++` is atomic in JS's single-threaded event loop. | Workers are eagerly created. If `items.length << concurrency`, idle workers exist. Negligible for ETL scales (>1k items). |
| **Token Bucket with `setTimeout` Sleep** | Simple, memory-efficient, and accurately enforces `maxRPS` across all workers without external dependencies. | `setTimeout` has ~4ms resolution in Node.js. Sub-millisecond precision is lost, but irrelevant for ETL RPS limits (typically 1-1000). |
| **Full Jitter Backoff** | `base * 2^attempt + random(0, base)` prevents thundering herd and aligns with AWS/Stripe retry best practices. | Slightly higher average latency vs. linear backoff, but dramatically reduces upstream load during degradation. |
| **Unordered Results Collection** | `result.results` pushes synchronously on success. Maintains low memory overhead and avoids index-mapping complexity. | Output order doesn't match input order. For ETL, order is typically irrelevant. If needed, wrap results in `{ index, data }` and sort post-run. |
| **AbortSignal Integration** | Checks `signal.aborted` before every blocking operation. Waits are interruptible via `addEventListener('abort')`. | Slight boilerplate per wait. Ensures clean shutdown without zombie timers or hanging promises. |

