export interface EtlQueueOptions {
  /** Maximum number of jobs running simultaneously */
  concurrency: number;
  /** Maximum job initiations per second across all workers */
  maxRPS: number;
  /** Base delay in ms for exponential backoff */
  retryBaseDelayMs: number;
  /** Maximum delay in ms for backoff (prevents runaway waits) */
  maxRetryDelayMs?: number;
  /** Number of retries after initial failure */
  maxRetries: number;
  /** Optional abort signal for graceful cancellation */
  signal?: AbortSignal;
}

export type EtlJob<T, R> = (item: T, signal: AbortSignal) => Promise<R>;

export interface EtlQueueResult<R> {
  successes: number;
  failures: number;
  errors: Array<{ item: unknown; error: unknown }>;
  results: R[];
}

/**
 * Internal token-bucket rate limiter.
 * Limits job *initiation* rate, not completion rate.
 */
class TokenBucket {
  private tokens: number;
  private lastRefill: number;

  constructor(private readonly maxRPS: number) {
    this.tokens = maxRPS;
    this.lastRefill = Date.now();
  }

  private refill(): void {
    const now = Date.now();
    const elapsed = (now - this.lastRefill) / 1000;
    this.tokens = Math.min(this.maxRPS, this.tokens + elapsed * this.maxRPS);
    this.lastRefill = now;
  }

  async acquire(signal: AbortSignal): Promise<void> {
    while (true) {
      if (signal.aborted) throw new DOMException('Operation aborted', 'AbortError');
      this.refill();
      if (this.tokens >= 1) {
        this.tokens -= 1;
        return;
      }
      const waitMs = ((1 - this.tokens) / this.maxRPS) * 1000;
      await waitForAbortOrTimeout(waitMs, signal);
    }
  }
}

function waitForAbortOrTimeout(ms: number, signal: AbortSignal): Promise<void> {
  return new Promise<void>((resolve, reject) => {
