```ts
export class AsyncCache<T> {
  private cache = new Map<string, {
    promise: Promise<T>;
    expiry: number;
  }>();

  private readonly ttlMs: number;
  private readonly maxSize: number;

  constructor(options: { ttlMs?: number; maxSize?: number } = {}) {
    this.ttlMs = options.ttlMs ?? 5 * 60 * 1000; // 5 min default
    this.maxSize = options.maxSize ?? 1000;
  }

  async get(key: string, loader: (key: string) => Promise<T>): Promise<T> {
    let entry = this.cache.get(key);

    // 1. Evict expired entries
    if (entry && Date.now() > entry.expiry) {
      this.cache.delete(key);
      entry = undefined;
    }

    // 2. Return cached in-flight or fulfilled promise
    if (entry) {
      return entry.promise;
    }

    // 3. Create promise with automatic failure cleanup
    const promise = Promise.resolve(loader(key)).catch(err => {
      // Remove rejected promises to allow retries on subsequent calls
      this.cache.delete(key);
      throw err;
    });

    // 4. Enforce max size (FIFO eviction)
    if (this.cache.size >= this.maxSize) {
      const oldestKey = this.cache.keys().next().value;
      this.cache.delete(oldestKey);
    }

    // 5. Store BEFORE returning to coalesce concurrent requests
    this.cache.set(key, { promise, expiry: Date.now() + this.ttlMs });

    return promise;
  }

  invalidate(key: string): void {
    this.cache.delete(key);
  }

  clear(): void {
    this.cache.clear();
  }
}
```

#### 📦 Usage
```ts
const cache = new AsyncCache<Data>({ ttlMs: 60_000, maxSize: 500 });

async function loadUser(id: string): Promise<Data> {
  return cache.get(`user:${id}`, async (key) => {
    // Simulate network call
    const res = await fetch(`https://api.example.com/users/${id}`);
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    return res.json();
  });
}
```

